"""Hive auto-rig: Blender scene builder (generated by hive-rig).

Builds every character of a hive-rig scene in one Blender file, each from its
own builder script next to this one (`<character>_blender.py`), and stands it
where the scene places it. Props held across characters get a `held` setting
on the prop's control (0: it stays on its own socket, 1: it follows the
holder's bone), driving a Child Of constraint on that control.

Run inside Blender 3.6+ (Scripting tab > Open > Run Script), or headless:
    blender --background --python <this file> -- --save scene.blend
Running it again only builds the characters that aren't in the file yet.
"""

import json
import os
import sys

import bpy
from mathutils import Vector

SCENE = json.loads(r"""__HIVE_SCENE_JSON__""")
HERE = os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else os.getcwd()


def to_blender(p):
    """Hive space is Y-up / +Z forward; Blender is Z-up / -Y forward."""
    return Vector((p[0], -p[2], p[1]))


def load_character(c):
    """Run a character's builder script as a module and return its globals."""
    path = os.path.join(HERE, c["script"])
    if not os.path.isfile(path):
        raise RuntimeError("hive-rig: %s is missing; export %s from the scene again" % (path, c["name"]))
    ns = {"__name__": "hive_scene_" + c["name"], "__file__": path}
    with open(path) as f:
        exec(compile(f.read(), path, "exec"), ns)
    return ns


def build_character(c):
    """Build one character (or find it built) and stand it in its place."""
    ns = load_character(c)
    rig = bpy.data.objects.get(c["name"] + "_rig")
    if rig is None or not rig.get("hive_guides"):
        rig, _ = ns["build"](ns["RIG_DATA"])
        ns["add_studio_pose"](rig, ns["RIG_DATA"])
    rig.location = to_blender(c["offset"])
    rig["hive_scene"] = SCENE["name"]
    return rig, ns


def hold(h, rigs):
    """The prop's control follows the holder's bone by its `held` setting."""
    prop_rig, holder_rig = rigs[h["prop_character"]], rigs[h["holder_character"]]
    pb = prop_rig.pose.bones[h["prop_control"]]
    holder = holder_rig.pose.bones[h["holder_bone"]]
    name = "Held by " + h["holder_character"]
    con = pb.constraints.get(name) or pb.constraints.new("CHILD_OF")
    con.name = name
    con.target = holder_rig
    con.subtarget = holder.name
    bpy.context.view_layer.update()
    # Keep the prop where it is now: the holder's bone as it stands is the
    # constraint's starting point.
    con.inverse_matrix = (holder_rig.matrix_world @ holder.matrix).inverted()
    if hasattr(con, "set_inverse_pending"):
        con.set_inverse_pending = False
    pb["held"] = float(h["held"])
    try:
        pb.id_properties_ui("held").update(min=0.0, max=1.0, soft_min=0.0, soft_max=1.0,
                                           description="0: on its own socket, 1: in %s's hand" % h["holder_character"])
    except (AttributeError, TypeError):
        pass
    con.driver_remove("influence")
    drv = con.driver_add("influence").driver
    drv.type = "AVERAGE"
    var = drv.variables.new()
    var.name = "held"
    var.targets[0].id = prop_rig
    var.targets[0].data_path = 'pose.bones["%s"]["held"]' % pb.name
    pb["hive_held_by"] = json.dumps({"character": h["holder_character"], "bone": h["holder_bone"]})
    return con


def build():
    rigs, last = {}, None
    for c in SCENE["characters"]:
        rigs[c["name"]], last = build_character(c)
    for h in SCENE["holds"]:
        hold(h, rigs)
    bpy.context.view_layer.update()
    if last is not None:
        last["register"]()  # the Hive tab, which works on whichever rig is active
    return rigs


def main():
    rigs = build()
    print("hive-rig: scene %s with %d characters (%s) and %d held props"
          % (SCENE["name"], len(rigs), ", ".join(rigs), len(SCENE["holds"])))
    if "--" in sys.argv:
        args = sys.argv[sys.argv.index("--") + 1:]
        if "--save" in args:
            bpy.ops.wm.save_as_mainfile(filepath=args[args.index("--save") + 1])


if __name__ == "__main__":
    main()
